function resetGame(seed) {
  rng = mulberry32(seed);
  score = 0;
  lives = 3;
  gameState = 'PLAYING';

  paddle = {
    w: 120,
    h: 12,
    x: 140,
    y: 370,
    speed: 8
  };

  resetBalls();

  bricks = [];
  let rows = 6 + Math.floor(rng() * 6);
  let cols = 16;
  let bw = 400 / cols;
  let bh = 12;

  for (let r = 0; r < rows; r++) {
    let rColor = [
      50 + Math.floor(rng() * 205),
      50 + Math.floor(rng() * 205),
      50 + Math.floor(rng() * 205)
    ];
    for (let c = 0; c < cols; c++) {
      if (rng() > 0.1) {
        bricks.push({
          x: c * bw + 2,
          y: r * bh + 30,
          w: bw - 4,
          h: bh - 4,
          active: true,
          color: rColor
        });
      }
    }
  }
}
